const TABS=[['all','Semua',()=>1],['draft','Draft',r=>r.status=='Draft'],['wait','Menunggu',r=>r.status=='Menunggu persetujuan'],['run','Berjalan',r=>['Disetujui','Dana dicairkan','Dalam pertanggungjawaban'].includes(r.status)],['rev','Perlu revisi',r=>r.status=='Perlu revisi'],['done','Selesai',r=>r.status=='Selesai'],['rej','Ditolak',r=>r.status=='Ditolak']];
