const fbtnH=k=>{const t=TABS.find(x=>x[0]==k);return `<span class=fl>${FI.flt}</span><span class=ft><small>Status:</small><b>${t[1]}</b></span><em>${fCnt(k)}</em><span class=fcv>${FI.cv}</span>`};
const fmenuH=k=>TABS.map(([c,t])=>`<button type=button role=option aria-selected="${c==k}" class="fopt${c==k?' on':''}" onclick="fSel('${c}')"><i class=fdot style="background:${FDX[c][0]}"></i><span class=fo>${t}</span><span class=fc>${fCnt(c)}</span><span class=fck>${FI.ck}</span></button>`).join('');
function fClose(){const d=$('fdd');if(!d)return;d.classList.remove('open');$('fbtn').setAttribute('aria-expanded','false')}
function fddT(){const d=$('fdd'),o=d.classList.toggle('open');$('fbtn').setAttribute('aria-expanded',o)}
function fSel(k){window._tf=k;$('fbtn').innerHTML=fbtnH(k);$('fmenu').innerHTML=fmenuH(k);$('lt').innerHTML=rows();fClose()}
