const STP=['Diajukan','Disetujui','Dicairkan','Pertanggungjawaban','Selesai'];
const rc=r=>{const rj=r.status=='Ditolak',rv=r.status=='Perlu revisi',rb=isRb(r),SP=noPay(r)?['Diajukan + nota','Disetujui','Selesai']:rb?['Diajukan + nota','Disetujui','Dibayarkan','Selesai']:STP,cur=noPay(r)?({'Selesai':2}[r.status]??0):rb?({'Disetujui':1,'Selesai':3}[r.status]??0):SI[r.status]??0,wt=me().role=='Admin'&&r.status=='Menunggu persetujuan',tone=(rj?'t-rj':rv?'t-rv':r.status=='Selesai'?'t-ok':'')+(wt?' wait':'');return `<div class="rcd ${tone}" onclick="go('det',${r.id})"><span class=ci>${IC.list}</span><div class=rm><b>${esc(r.title)}</b>${wt?'<div style="margin:0 0 5px"><span class=wtag>Perlu persetujuan Anda</span></div>':''}<div class=rmeta><span class=rno>${r.no}</span>${jTag(r)}<span>${esc(r.cat)}</span><span>${r.date}</span>${r.rab?'<span>RAB '+mLabel(r.rab.ym)+'</span>':''}${r.rab&&r.amt!=r.rab.total?'<span class=rwn>Berbeda dari RAB</span>':''}</div><div class=seg>${SP.map((t,k)=>`<i class="${!rj&&r.status!='Draft'&&k<=cur?'on':''}" title="${t}"></i>`).join('')}</div><small class=stl>${rj?'Request ditolak':r.status=='Draft'?'Draft belum diajukan ke pimpinan':rv?'Perlu direvisi sebelum diproses':r.status=='Selesai'?'Seluruh tahapan selesai':`Tahap ${cur+1} dari ${SP.length} · ${SP[cur]}`}</small></div><div class=rr><small>${r.approved!=null?'Disetujui':'Diajukan'}</small><b>${Rp(r.approved!=null?r.approved:r.amt)}</b><span class="${bc(r.status)}">${r.status}</span></div>${SV.chev}</div>`};
const rows=()=>{const fn=TABS.find(t=>t[0]==(window._tf||'all'))[2],L=fq().filter(fn);return L.map(rc).join('')||`<div class=empty>${IC.list}<b>Tidak ada request</b><small>${window._q?'Tidak ada hasil untuk pencarian Anda. Coba kata kunci lain.':'Belum ada data pada kategori ini.'}</small></div>`};
function list(){const f=window._tf||'all',q=window._q||'',cn=k=>S.reqs.filter(TABS.find(t=>t[0]==k)[2]).length,A=S.reqs,sm=g=>A.reduce((t,r)=>t+(+g(r)||0),0),K=[['Total request',A.length,`${cn('wait')} menunggu · ${cn('run')} berjalan`,IC.list],['Dana diajukan',Rp(sm(r=>r.amt)),'seluruh request',IC.new],['Dana disetujui',Rp(sm(r=>r.approved)),`${A.filter(r=>r.approved!=null).length} request`,IC.audit],['Dana dicairkan',Rp(sm(r=>r.disb&&r.disb.amt)),`${A.filter(r=>r.disb).length} pencairan`,IC.rep]];
return `<div class="kpis kpis-s">${K.map(([a,b,c,i])=>`<div class=kpi><div class=kh><span>${a}</span><i class=ci>${i}</i></div><b>${b}</b><small>${c}</small></div>`).join('')}</div><div class=box><div class=lh><div class=fdd id=fdd><button type=button class=fbtn id=fbtn onclick="fddT()" aria-haspopup=listbox aria-expanded=false>${fbtnH(f)}</button><div class=fmenu id=fmenu role=listbox>${fmenuH(f)}</div></div><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><div class=srch>${SV.srch}<input placeholder="Cari no. / kegiatan..." value="${esc(q)}" oninput="window._q=this.value;clearTimeout(window._t);window._t=setTimeout(()=>{$('lt').innerHTML=rows()},200)"></div>${me().role=='Bendahara'?`<button class=btn onclick="go('new')">+ Buat Request</button>`:''}</div></div><div id=lt class=rl>${rows()}</div></div>`}
const fq=()=>S.reqs.filter(r=>(r.no+r.title).toLowerCase().includes((window._q||'').toLowerCase()));
const fmtD=v=>v?new Date(v+'T00:00').toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'}):'-';
const form=()=>`<div style="margin:0 0 14px"><button class="btn o bk" onclick="go('list')">${SV.back} Kembali ke daftar request</button></div><div class=dgrid oninput="sumUp()" onchange="sumUp()">${form0()}<div class=side><div class="box sumc"><h4>Ringkasan Pengajuan</h4><div class=sumn><small>Nominal diajukan</small><b id=sa>${Rp(0)}</b></div><div class=sumr><span>Kategori</span><b id=sc>${esc(CATS[0])}</b></div><div class=sumr><span>Kegiatan</span><b id=st>-</b></div><div class=sumr><span>Dibutuhkan pada</span><b id=sd>${fmtD(today())}</b></div><div class=sumr><span>Pengaju</span><b>${esc(me().name)}</b></div></div><div class="box flow" id=flw>${flowH('cair')}</div><div class=lockb>${SV.lock}<span id=flk>${FLK.cair}</span></div></div></div>`;
function sumUp(){const g=i=>$(i),v=i=>g(i)?g(i).value:'';if(!g('sa'))return;g('sa').textContent=Rp(num('fa')||0);g('sc').textContent=v('fc');g('st').textContent=v('ft').trim()||'-';g('sd').textContent=fmtD(v('fd'));if(g('ft'))g('ft').classList.remove('err');if(g('fa'))g('fa').classList.remove('err')}
function showFf(el){const F=[...el.files],bx=el.parentNode.querySelector('.fnm');if(!F.length){bx.innerHTML='';return}const rb=fjV()!='cair',lim=rb?8e6:1e6;bx.innerHTML=F.map(f=>{const big=f.size>lim;return `<div class="fchip${big?' bad':''}"><span>${NI.pdf}</span><div><b>${esc(f.name)}</b><small>${(f.size/1024).toFixed(0)} KB${big?' · melebihi '+(rb?'8':'1')+' MB':''}</small></div><button type=button onclick="event.stopPropagation();rmFf()" aria-label="Hapus berkas">${NI.x}</button></div>`}).join('')}
function rmFf(){const e=$('ff');e.value='';showFf(e)}
function form0(){return `<div class="box fbox"><div class=fsec><i>1</i><div><h4>Informasi Pengajuan</h4><small>Tentukan kategori, kegiatan, dan jumlah dana yang dibutuhkan.</small></div></div><label class=req>Jenis pengajuan</label><div class=jnp id=fjw><label class="jno on"><input type=radio name=fj value=cair checked onchange="fjChg()"><b>Pencairan dana</b><small>Minta dana dulu, belanja, lalu unggah nota (LPJ).</small></label><label class=jno><input type=radio name=fj value=rb onchange="fjChg()"><b>Reimburse</b><small>Sudah dibayar lebih dulu. Nota dilampirkan saat pengajuan, setelah disetujui tidak perlu unggah nota lagi.</small></label><label class=jno><input type=radio name=fj value=kk onchange="fjChg()"><b>Kas kecil</b><small>Melaporkan belanja yang dibayar dari kas kecil. Tanpa pencairan dana, hanya nota dan persetujuan pimpinan.</small></label></div><div id=kkInfo class="aps warn" style="display:none;margin-top:12px"></div><div id=srw style="display:none;margin-top:14px"><label class=req>Sumber dana</label><div class=srp>${Object.entries(SRC).map(([k,t])=>`<label class=sro><input type=radio name=fs value=${k} onchange="fsChg()"><b>${t}</b><small id=fsS_${k}>${k=='pim'?'Pimpinan membayar ke bendahara setelah disetujui':'Saldo: -'}</small></label>`).join('')}</div></div><div id=rbw style="display:none">${rbPaidH(null,'rbpf')}</div><div class=g2 style="margin-top:14px"><div><label class=req>Kategori</label><select id=fc>${CATS.map(c=>`<option>${c}</option>`).join('')}</select></div><div><label class=req>Nama kegiatan / keperluan</label><input id=ft placeholder="Contoh: Konsumsi rapat mingguan" maxlength=120></div><div id=fshw style="display:none"><label>Toko / penyedia</label><input id=fsh maxlength=100 placeholder="Contoh: SPBU Way Halim"></div><div id=faw><label class=req id=fal>Nominal diajukan</label><div class=pre><span>Rp</span><input id=fa class=rp inputmode=numeric placeholder="1.500.000" autocomplete=off></div></div><div><label>Tanggal kebutuhan dana</label><input id=fd type=date value="${today()}"></div></div><div class=fsec style="margin-top:28px"><i>2</i><div><h4>Rincian Kebutuhan</h4><small>Jelaskan tujuan dan rincian penggunaan agar mudah disetujui.</small></div></div><label>Deskripsi kebutuhan</label><textarea id=fx rows=4 maxlength=500 placeholder="Contoh: Pembelian konsumsi untuk rapat koordinasi 20 peserta, termasuk air mineral." oninput="this.nextElementSibling.textContent=this.value.length+' / 500'"></textarea><small class=cnt>0 / 500</small><div class=fsec style="margin-top:28px"><i>3</i><div><h4 id=fdH>Dokumen Pendukung <em>opsional</em></h4><small id=fdS>Lampirkan surat tugas, undangan, atau RAB bila ada.</small></div></div><div class=drop id=fdrop onclick="if(!event.target.closest('.fnm'))$('ff').click()" ondragover="event.preventDefault();this.classList.add('ov')" ondragleave="this.classList.remove('ov')" ondrop="event.preventDefault();this.classList.remove('ov');$('ff').files=event.dataTransfer.files;showFf($('ff'))"><svg viewBox="0 0 24 24"><path d="M12 16V4M7 9l5-5 5 5M4 20h16"/></svg><b id=fdB>Klik atau seret berkas ke sini</b><small id=fdL>JPG, PNG, atau PDF · maks 1 MB</small><input id=ff type=file hidden accept=".jpg,.jpeg,.png,.pdf" onchange="showFf(this)"><div class=fnm></div></div><div class=fbar><small id=fbh>Simpan sebagai draft bila belum siap dikirim.</small><div id=fbb><button class="btn o" onclick="saveReq(0)">Simpan Draft</button><button class=btn onclick="saveReq(1)">Kirim Pengajuan</button></div></div></div>`}
const FL={kk:[['Laporkan penggunaan','Isi keperluan dan nominal, lalu lampirkan nota belanja dari kas kecil.'],['Persetujuan Pimpinan','Pimpinan memeriksa nota, lalu menyetujui atau menolak.'],['Selesai','Tidak ada pencairan dana. Pengeluaran otomatis tercatat di Kas Kecil.']],cair:[['Ajukan request','Isi kebutuhan dan nominal dana.'],['Persetujuan Pimpinan','Disetujui, ditolak, atau diminta revisi.'],['Pencairan dana','Dana dicairkan sesuai nominal disetujui.'],['Realisasi & nota','Catat pengeluaran dan unggah nota.'],['LPJ otomatis','Dokumen PDF disusun dari data yang diinput.']],rb:[['Ajukan reimburse','Isi kegiatan, lalu lampirkan semua nota belanja.'],['Persetujuan Pimpinan','Pimpinan memeriksa nota, lalu menyetujui, meminta revisi, atau menolak.'],['Pembayaran reimburse','Pimpinan membayar ke bendahara. Jika sudah dibayar sebelumnya, langkah ini otomatis.'],['Selesai','Tidak perlu unggah nota lagi. LPJ langsung bisa dicetak.']]},FLK={kk:'Nota wajib dilampirkan. Tidak ada pencairan dana; setelah disetujui langsung selesai.',cair:'Setelah dikirim, data request tidak dapat diubah. Nota boleh diunggah menyusul.',rb:'Nota wajib dilampirkan sebelum dikirim. Setelah dikirim, data dan nota terkunci.'};
const flowH=j=>`<h4>${j=='rb'?'Alur Reimburse':j=='kk'?'Alur Kas Kecil':'Alur Pengajuan'}</h4>`+FL[j].map(([a,b],i)=>`<div class="gs${i==0?' now':''}"><b>${i+1}</b><div><b>${a}</b><small>${b}</small></div></div>`).join('');
const rbPaidH=(p,id)=>`<div class=rbp id=${id}><label class=ck><input type=checkbox id=rpC ${p?'checked':''} onchange="$('rpF').style.display=this.checked?'':'none';${id=='rbpd'?'rbPaidSet()':''}"><span>Sudah direimburse (uang sudah dibayarkan ke bendahara)<small>Centang jika reimburse ini sudah dibayar sebelum diinput ke sistem. Setelah pimpinan menyetujui, request langsung <b>Selesai</b> tanpa langkah pembayaran.</small></span></label><div class=g2 id=rpF style="${p?'':'display:none'}"><div><label>Tanggal dibayarkan</label><input type=date id=rpD value="${p?p.date:today()}" max="${today()}" ${id=='rbpd'?'onchange="rbPaidSet()"':''}></div><div><label>Metode</label><select id=rpM ${id=='rbpd'?'onchange="rbPaidSet()"':''}>${['Transfer','Tunai'].map(o=>`<option ${p&&p.method==o?'selected':''}>${o}</option>`).join('')}</select></div></div></div>`;
const rbPaidV=()=>$('rpC')&&$('rpC').checked?{date:$('rpD').value||today(),method:$('rpM').value}:null;
function rbPaidSet(){const r=R_();if(!rbOpen(r))return;r.rbPaid=rbPaidV();log(`${r.no}: status reimburse ${r.rbPaid?'sudah dibayarkan ('+r.rbPaid.date+')':'belum dibayarkan'}`);save()}
const fjV=()=>(document.querySelector('input[name=fj]:checked')||{}).value||'cair';
const fsV=()=>(document.querySelector('input[name=fs]:checked')||{}).value||'pim';
function fsChg(){const s=fsV();document.querySelectorAll('.sro').forEach(l=>l.classList.toggle('on',l.querySelector('input').checked));$('rbw').style.display=fjV()!='cair'&&s=='pim'?'':'none';const ki=$('kkInfo');if(ki){ki.style.display=fjV()!='cair'&&s!='pim'?'':'none';if(typeof kSaldoW=='function')ki.innerHTML='Saldo '+SRC[s].toLowerCase()+' tercatat saat ini: <b>'+Rp(kSaldoW(s))+'</b>. Tidak ada pencairan dana; setelah disetujui pimpinan, pengeluaran ini otomatis tercatat di '+SRC[s]+'.'}}
function fjChg(){const jv=fjV(),rb=jv!='cair',kk=jv=='kk';$('srw').style.display=rb?'':'none';if(rb){const d=document.querySelector('input[name=fs][value='+(kk?'kas':'pim')+']');if(d&&!document.querySelector('input[name=fs]:checked')||window._fjPrev!=jv)d.checked=true}window._fjPrev=jv;if(typeof kSaldoW=='function')['kas','rbf'].forEach(k=>{const e=$('fsS_'+k);if(e)e.textContent='Saldo: '+Rp(kSaldoW(k))});fsChg();if($('flw'))$('flw').innerHTML=flowH(jv);if($('flk'))$('flk').textContent=FLK[jv];document.querySelectorAll('#fjw .jno').forEach(l=>l.classList.toggle('on',l.querySelector('input').checked));$('fshw').style.display=rb?'':'none';$('fal').textContent=kk?'Nominal dipakai dari kas kecil':rb?'Total reimburse (sesuai nota)':'Nominal diajukan';$('fdH').innerHTML=rb?'Foto / Scan Nota <em style="background:#fde8e8;color:#b42318">wajib</em>':'Dokumen Pendukung <em>opsional</em>';$('fdS').textContent=rb?'Nota otomatis masuk ke bagian Realisasi & Bukti Nota. Boleh lebih dari satu file.':'Lampirkan surat tugas, undangan, atau RAB bila ada.';$('fdB').textContent=rb?'Klik atau seret foto nota ke sini':'Klik atau seret berkas ke sini';$('fdL').textContent=rb?'JPG, PNG, atau PDF · bisa beberapa file · maks 8 MB per file':'JPG, PNG, atau PDF · maks 1 MB';const ff=$('ff');ff.multiple=rb;showFf(ff);$('fbh').textContent=rb?'Nota akan terkunci setelah dikirim. Nota tambahan bisa dilampirkan selama masih draft.':'Simpan sebagai draft bila belum siap dikirim.'}
async function saveReq(send){const jn=fjV(),rb=jn!='cair',t=$('ft').value.trim(),a=num('fa');if(rb&&t&&a>0&&!$('ff').files.length)return alert('Lampirkan foto/scan nota.');if(!t||!(a>0)){$('ft').classList.toggle('err',!t);$('fa').classList.toggle('err',!(a>0));(!t?$('ft'):$('fa')).focus();return alert('Isi nama kegiatan dan nominal > 0')}let f=null,nota=[];if(rb){for(const fi of $('ff').files){if(fi.size>8e6)return alert(fi.name+': ukuran nota maks 8 MB');nota.push(fi.type=='application/pdf'||/\.pdf$/i.test(fi.name)?await rd(fi):await shrink(fi))}}else{const fi=$('ff').files[0];if(fi){if(fi.size>1e6)return alert('File maks 1 MB');f={name:fi.name,url:await rd(fi)}}}
const d=new Date(),id=S.seq,no=`OPS/${d.getFullYear()}/${String(d.getMonth()+1).padStart(2,'0')}/${String(S.seq++).padStart(4,'0')}`;
const r={id,no,jenis:jn,src:rb?fsV():null,rbPaid:rb&&fsV()=='pim'?rbPaidV():null,by:me().name,date:today(),cat:$('fc').value,title:t,desc:$('fx').value,amt:a,need:$('fd').value,file:f,status:'Draft',approved:null,hist:[],disb:null,tx:rb?[{shop:$('fsh').value.trim()||t,date:$('fd').value||today(),cat:$('fc').value,desc:$('fsh').value.trim()?t:($('fx').value.trim()||'Nota reimburse'),amt:a,imgs:nota}]:[],lpj:null};S.reqs.unshift(r);log('Membuat '+(jn=='kk'?'laporan kas kecil ':rb?'reimburse ':'request ')+no);if(send)sub(r);save();go('det',id)}
const rd=f=>API.upload(f,f.name);
function sub(r){const df=r.rab&&r.amt!=r.rab.total;r.status='Menunggu persetujuan';r.hist.push({t:now(),u:me().name,s:r.status,n:'Pengajuan dikirim'+(df?' (nominal berbeda dari RAB: '+Rp(r.amt)+' vs '+Rp(r.rab.total)+')':'')});log('Mengirim request '+r.no+(df?' (berbeda dari RAB)':''));note('Admin',(isKk(r)?'Laporan kas kecil masuk: ':isRb(r)?'Reimburse baru masuk: ':'Request baru masuk: ')+r.no+(df?' - nominal berbeda dari RAB ('+Rp(r.amt)+' vs '+Rp(r.rab.total)+')':''))}
const R_=()=>S.reqs.find(r=>r.id==cur);
const txList=(r,open)=>`<div class=txl>${r.tx.map((x,i)=>{const L=imgs(x);return `<div class="txc${x.rv?' rv-'+x.rv:''}"><div class=txn>${i+1}</div><div class=txb><div class=txt><div><b>${esc(x.shop)}</b><div class=mu>${esc(x.desc)}</div><div class=meta><span>${NI.cal}${x.date}</span><span>${NI.tag}${esc(x.cat)}</span></div></div><div class=amt>${Rp(x.amt)}</div></div><div class=nhd><span>${NI.rc}Bukti nota</span><em class="${L.length?'ok':'no'}">${L.length?L.length+' file':'Belum ada'}</em></div><div class=ngal>${L.map((u,j)=>{const im=isImg(u);return `<div class="nti${im?'':' pf'}"><button type=button class=nth onclick="viewNota(${i},${j})" aria-label="Lihat nota ${j+1}">${im?`<img src="${u}" alt="Nota ${j+1}" loading=lazy>`:`<span class=pfi>${NI.pdf}<b>PDF</b></span>`}<span class=nov>${NI.eye}<span>Lihat nota</span></span></button><span class=nix>${j+1}</span>${open?`<button type=button class=ndl onclick="delImg(${i},${j})" title="Hapus nota" aria-label="Hapus nota">${NI.x}</button>`:''}</div>`}).join('')}${open?`<button type=button class="nti add" onclick="this.nextElementSibling.click()">${NI.plus}<span>${L.length?'Tambah nota':'Unggah nota'}</span></button><input type=file multiple hidden accept=".jpg,.jpeg,.png,.pdf" onchange="upNota(${i},this)">`:(L.length?'':`<div class=nem>${NI.rc}<span>Belum ada nota untuk transaksi ini</span></div>`)}</div>${rvBar(r,i)}${open?`<div class=txa><button class="btn r" onclick="delTx(${i})">${NI.trash}Hapus transaksi</button></div>`:''}</div></div>`}).join('')||`<div class=empty>${IC.list}<b>Belum ada transaksi</b><small>${isRb(r)?'Isi toko, uraian, nominal, dan unggah nota pada formulir di bawah.':'Tambahkan pengeluaran dan unggah nota pada formulir di bawah.'}</small></div>`}</div>`;
function rbBox(r,open){const c=ckNota(r);return `<div class=box><div class=rzh><div><h3>Realisasi &amp; Bukti Nota</h3><small>${open?(noPay(r)?'Belanja yang dibayar dari '+SRCN(r).toLowerCase()+'. Lampirkan nota setiap transaksi, lalu kirim ke pimpinan.':'Belanja yang sudah dibayar bendahara. Lampirkan nota setiap transaksi, lalu kirim ke pimpinan.'):'Nota dilampirkan bendahara saat pengajuan. Tidak perlu unggah nota lagi setelah disetujui.'}</small></div>${jTag(r)}</div>
<div class=stats><div><small>Total nota</small><b>${Rp(c.t)}</b></div><div><small>Disetujui</small><b>${r.approved!=null?Rp(r.approved):'-'}</b></div><div><small>${noPay(r)?'Sumber dana':'Dibayarkan'}</small><b>${noPay(r)?SRCN(r):r.disb?Rp(r.disb.amt):r.rbPaid?'Sudah':'Belum'}</b>${!r.disb&&r.rbPaid?`<small style="text-transform:none;letter-spacing:0">${fmtD(r.rbPaid.date)} · ${esc(r.rbPaid.method)}</small>`:''}</div><div><small>Transaksi / nota</small><b>${c.n} / ${c.files}</b></div></div>
${txList(r,open)}
${open?`<div class=sech>Tambah transaksi & nota</div><div id=xrows>${rowH(r.cat)}</div><div class=bar2><button class="btn o" onclick="addRow()">+ Tambah toko lain</button><button class=btn onclick="saveTx()">Simpan Semua</button></div>`:''}
${r.status=='Selesai'&&r.disb?`<div class=lpjb><div><b>Laporan Pertanggungjawaban (LPJ)</b><small>Reimburse sudah dibayarkan. LPJ dapat diunduh sebagai PDF.</small></div><div><button class="btn o" onclick="lpjView()">Preview / Generate LPJ (PDF)</button></div></div>`:''}</div>`}
/* Pimpinan boleh menghapus request apa pun (mis. data contoh); bendahara hanya draft miliknya. */
const bolehHapus=r=>me().role=='Admin'||(me().role=='Bendahara'&&r.by==me().name&&['Draft','Menunggu persetujuan','Perlu revisi','Ditolak'].includes(r.status));
async function hapusReq(){const r=R_();if(!r||!bolehHapus(r))return;const rows=[['Nomor',r.no],['Kegiatan',r.title],['Status',r.status],['Nominal',Rp(r.approved??r.amt)]];if(r.rab)rows.push(['RAB ikut terhapus',mLabel(r.rab.ym)]);if(r.disb)rows.push(['Dana dicairkan',Rp(r.disb.amt)]);if(r.tx.length)rows.push(['Transaksi & nota',r.tx.length+' transaksi']);
if(!await ask({tone:'bad',title:'Hapus request ini?',msg:'Request beserta '+(r.rab?'RAB, ':'')+'riwayat, transaksi, dan notanya akan dihapus permanen dan tidak muncul lagi di laporan.',rows,ok:'Hapus Permanen',no:'Batal'}))return;
S.reqs=S.reqs.filter(x=>x.id!==r.id);if(typeof kasW=='function'){for(const w of ['kas','rbf']){const k=kasW(w);k.tx=k.tx.filter(x=>x.req!==r.no)}}log('Menghapus request '+r.no+' ('+r.title+')');if(me().role=='Admin')note('Bendahara','Request '+r.no+' dihapus pimpinan');else if(r.status!='Draft')note('Admin','Request '+r.no+' ('+r.title+') dibatalkan dan dihapus bendahara');save();go('list')}
const kkCatat=(r,amt)=>{if(typeof kasW!='function')return;const k=kasW(srcOf(r)),bu=S.users.find(u=>u.name==r.by&&u.role=='Bendahara')||S.users.find(u=>u.role=='Bendahara')||{};k.tx=k.tx.filter(x=>x.req!==r.no);k.seq=(k.seq||0)+1;const ds=r.tx.map(x=>x.date).filter(Boolean).sort();k.tx.push({id:k.seq,t:'out',date:ds[ds.length-1]||r.date,desc:r.title,amt,note:'Dari request '+r.no,cat:r.cat,shop:[...new Set(r.tx.map(x=>x.shop).filter(s=>s&&s!='-'))].join(', '),nota:r.tx.flatMap(x=>imgs(x)),uid:bu.u||'',by:r.by,at:now(),req:r.no})};
const rbJadiOk=r=>!isRb(r)&&!r.rab&&!r.tx.length&&(['Menunggu persetujuan','Disetujui'].includes(r.status)||(r.status=='Dana dicairkan'&&r.file&&canView(r.file.url)&&(!r.lpj||r.lpj.st=='Draft')));
const rbJadiBox=r=>!rbJadiOk(r)?'':r.status=='Dana dicairkan'?`<div class="aps" style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin:0;background:#eef6f0;color:#14532d"><span><b>Lampiran ini adalah nota dari belanja yang sudah dibayar?</b> Proses sebagai <b>reimburse</b>: lampiran dipindah ke Realisasi &amp; Bukti Nota dan request langsung <b>Selesai</b>, tanpa bendahara mengunggah nota lagi.</span><button type=button class="btn o" onclick="act('rbjadi')">Proses sebagai Reimburse</button></div>`:`<div class="aps" style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin:0 0 18px;background:#eef6f0;color:#14532d"><span><b>Belanja ini sudah dibayar bendahara?</b> Proses sebagai <b>reimburse</b>${r.file&&canView(r.file.url)?': lampiran akan dipindah ke Realisasi &amp; Bukti Nota':''}, sehingga setelah disetujui bendahara tidak perlu unggah nota lagi.</span><button type=button class="btn o" onclick="act('rbjadi')">Proses sebagai Reimburse</button></div>`;
/* Ganti jenis pengajuan (pencairan / reimburse / kas kecil) selama belum disetujui. */
const JN={cair:'Pencairan dana',rb:'Reimburse',kk:'Kas kecil'},jnOf=r=>noPay(r)?'kk':isRb(r)?'rb':'cair';
const jnBoleh=r=>!r.rab&&['Draft','Perlu revisi','Menunggu persetujuan'].includes(r.status)&&(me().role=='Admin'||me().role=='Bendahara');
let JNO=false;
const jnBar=r=>!jnBoleh(r)?(isRb(r)?`<div class=jnb><span>Sumber dana: <b>${SRCN(r)}</b></span></div>`:''):`<div class=jnb><span>Jenis pengajuan: <b>${JN[jnOf(r)]}</b></span>${isRb(r)?`<span>Sumber dana: <select onchange="act('src:'+this.value)" style="width:auto;padding:4px 8px;font-size:13px">${Object.entries(SRC).map(([k,t])=>`<option value=${k} ${srcOf(r)==k?'selected':''}>${t}</option>`).join('')}</select></span>`:''}${JNO===r.id?`<span class=jnc>${Object.keys(JN).filter(k=>k!=jnOf(r)).map(k=>`<button type=button class="btn o" onclick="act('jn:${k}')">Jadikan ${JN[k]}</button>`).join('')}<button type=button class=lnk2 onclick="JNO=false;draw()">Batal</button></span>`:`<button type=button class=lnk2 onclick="JNO=${r.id};draw()">Salah pilih? Ubah jenis</button>`}</div>`;
/* Bukti transfer pencairan / pembayaran reimburse (diunggah pimpinan) */
async function tfBaca(el){const out=[];for(const f of [...(el&&el.files||[])]){if(!/\.(jpe?g|png|webp|pdf)$/i.test(f.name))throw new Error(f.name+': harus JPG, PNG, WEBP, atau PDF.');if(f.size>8e6)throw new Error(f.name+': maksimal 8 MB.');out.push({name:f.name,url:/\.pdf$/i.test(f.name)?await rd(f):await shrink(f)})}return out}
const tfLink=r=>{const L=(r.disb&&r.disb.tf)||[],adm=me().role=='Admin',inp=adm?`<input id=tfUp type=file hidden multiple accept=".jpg,.jpeg,.png,.webp,.pdf" onchange="tfTambah(this)">`:'';
if(!L.length)return adm?`<button type=button class=tfup onclick="$('tfUp').click()"><svg viewBox="0 0 24 24"><path d="M12 16V4M7 9l5-5 5 5M4 20h16"/></svg><span><b>Unggah bukti transfer</b><small>JPG, PNG, atau PDF</small></span></button>${inp}`:`<div class=tfnone><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg>Bukti transfer belum diunggah pimpinan</div>`;
return `<div class=tfbox><div class=tfh><span>Bukti transfer</span>${adm?`<button type=button onclick="$('tfUp').click()">+ Tambah</button>`:''}</div><div class=tfls>${L.map((x,j)=>{const im=isImg(x.url),ext=(String(x.name||x.url).split('.').pop()||'').toUpperCase();return `<button type=button class=tfi onclick="tfLihat(${j})" title="Lihat ${esc(x.name||'bukti transfer')}">${im?`<img src="${esc(x.url)}" alt="" loading=lazy>`:`<i>PDF</i>`}<span><b>${L.length>1?'Bukti '+(j+1):'Bukti transfer'}</b><small>${esc(ext)} · lihat</small></span><svg viewBox="0 0 24 24"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/></svg></button>`}).join('')}</div>${inp}</div>`};
function tfLihat(j){const r=R_(),L=r.disb.tf;viewFile(L.map(x=>x.url),j,'Bukti transfer '+r.no,L.map(x=>x.name))}
async function tfTambah(el){const id=cur;if(!R_()||!R_().disb||me().role!='Admin')return;let tf;try{tf=await tfBaca(el)}catch(e){el.value='';return alert(e.message)}el.value='';if(!tf.length)return;const r=S.reqs.find(x=>x.id==id);if(!r||!r.disb)return;r.disb.tf=(r.disb.tf||[]).concat(tf);r.hist.push({t:now(),u:me().name,s:r.status,n:'Bukti transfer diunggah ('+tf.length+' file)'});log(`${r.no}: unggah bukti transfer (${tf.length} file)`);note('Bendahara',`Bukti transfer ${r.no} diunggah pimpinan (${tf.length} file)`);save();draw()}
function det(){if(!R_())return `<div class=box><div class=empty>${IC.list}<b>Request tidak ditemukan</b><small>Request ini mungkin sudah dihapus.</small></div><p style="text-align:center"><button class="btn o" onclick="go('list')">Kembali ke daftar request</button></p></div>`;const r=R_(),m=me().role,n=`<label>Catatan</label><textarea id=nt rows=2></textarea>`;let a='';
if(m=='Bendahara'&&['Draft','Perlu revisi'].includes(r.status))a=(r.rab?`<h4>Nominal Pengajuan</h4><p class=mu style="margin:2px 0 4px">Nominal awal mengikuti total RAB (${Rp(r.rab.total)}). Jika diubah, muncul peringatan dan pimpinan akan menerimanya saat request diajukan.</p><div class=g2><div><label>Nominal diajukan</label><div class=pre><span>Rp</span><input id=en class=rp inputmode=numeric value="${fm(r.amt)}" oninput="rabWarn()" autocomplete=off></div></div><div><label>Alasan perubahan (opsional)</label><input id=ea value="${esc(r.rab.note||'')}" maxlength=160 placeholder="Contoh: harga bahan naik"></div></div><div id=rw style="margin-top:6px">${rabBan(r,'Bendahara')}</div>`:'')+(isRb(r)?`<h4>${isKk(r)?'Penggunaan Kas Kecil':'Reimburse'} · <span style="font-weight:500">sumber dana: ${SRCN(r)}</span></h4><p class=mu style="margin:2px 0 6px">Lampirkan semua nota pada bagian <b>Realisasi &amp; Bukti Nota</b> di bawah. Nominal pengajuan otomatis sama dengan total nota (saat ini <b>${Rp(tot(r))}</b>). ${noPay(r)?'Tidak ada pencairan dana; setelah disetujui request langsung selesai dan tercatat di '+SRCN(r)+'.':'Setelah pimpinan menyetujui, Anda tidak perlu mengunggah nota lagi.'}</p>${noPay(r)?'':rbPaidH(r.rbPaid,'rbpd')}<div style="height:12px"></div>`:'')+`<div class=ama>${r.rab?`<button class="btn o" onclick="act('amt')">Simpan Nominal</button>`:''}<button class=btn onclick="act('send')">Kirim ke Pimpinan</button></div>`;
if(m=='Admin'&&r.status=='Menunggu persetujuan')a=rbJadiBox(r)+apPanel(r);
if(m=='Admin'&&r.status=='Disetujui')a=rbJadiBox(r)+`<h4>${isRb(r)?'Bayar Reimburse ke Bendahara':'Catat Pencairan'}</h4>${isRb(r)?'<p class=mu style="margin:2px 0 8px">Nota sudah dilampirkan saat pengajuan. Setelah pembayaran dicatat, request otomatis <b>Selesai</b>.</p>':''}<div class=g2><div><label>${isRb(r)?'Nominal dibayarkan':'Nominal dicairkan'} (maks ${Rp(r.approved)})</label><input id=da class=rp inputmode=numeric value="${fm(r.approved)}"></div><div><label>Tanggal</label><input id=dd type=date value="${today()}"></div><div><label>Metode</label><select id=dm><option>Transfer</option><option>Tunai</option></select></div><div><label>Penerima / rekening</label><input id=dr></div></div><label>Bukti transfer <em style="font-weight:400;color:var(--mu)">(opsional, bisa lebih dari satu)</em></label><input id=dtf type=file multiple accept=".jpg,.jpeg,.png,.webp,.pdf" style="padding:9px"><label>Catatan</label><input id=nt><button class=btn onclick="act('disb')">${isRb(r)?'Simpan Pembayaran Reimburse':'Simpan Pencairan'}</button>`;
if(m=='Admin'&&r.status=='Dana dicairkan'&&rbJadiOk(r))a=rbJadiBox(r);
let tx='';if(r.status!='Ditolak'&&nHide(r)){const rv=r.lpj&&r.lpj.ver>0;tx=`<div class=box><div class=rzh><div><h3>Realisasi &amp; Bukti Nota</h3></div></div><div class=empty style="margin-top:12px">${IC.list}<b>${rv?'Bendahara sedang memperbaiki nota':'Nota belum dikirim bendahara'}</b><small>${rv?'Nota akan tampil kembali setelah dikirim ulang.':'Nota dan realisasi akan tampil di sini setelah bendahara mengirimkannya.'}</small></div></div>`}else if(r.status!='Ditolak'&&isRb(r)){const open=m=='Bendahara'&&rbOpen(r);tx=rbBox(r,open)}else if(r.status!='Ditolak'){const open=m=='Bendahara'&&r.status!='Selesai'&&(!r.lpj||['Draft','Perlu revisi'].includes(r.lpj.st));
const done=tot(r),dsb=r.disb?+r.disb.amt:0,pct=dsb?Math.min(100,Math.round(done/dsb*100)):0,nn=r.tx.reduce((a,x)=>a+imgs(x).length,0);
tx=`<div class="box"><div class=rzh><div><h3>Realisasi & Bukti Nota</h3><small>Catat setiap pengeluaran beserta nota pendukungnya.</small></div>${r.lpj?`<span class="${bc(r.lpj.st)}">LPJ: ${r.lpj.st}</span>`:''}</div>
<div class=stats><div><small>Dana dicairkan</small><b>${r.disb?Rp(dsb):'Belum dicairkan'}</b></div><div><small>Total realisasi</small><b>${Rp(done)}</b></div><div><small>${dsb-done<0?'Kekurangan dana':'Sisa dana'}</small><b>${r.disb?Rp(Math.abs(dsb-done)):'-'}</b></div><div><small>Transaksi / nota</small><b>${r.tx.length} / ${nn}</b></div></div>
${r.disb?`<div class=prog><i style="width:${pct}%"></i></div><small class=pl>${pct}% dari dana yang dicairkan telah direalisasikan</small>`:''}
${txList(r,open)}
${open?`<div class=sech>Tambah transaksi & nota</div><div id=xrows>${rowH(r.cat)}</div><div class=bar2><button class="btn o" onclick="addRow()">+ Tambah toko lain</button><button class=btn onclick="saveTx()">Simpan Semua</button></div>`:''}
${r.disb&&!(m=='Admin'&&r.lpj&&r.lpj.st=='Menunggu verifikasi')?ckList(r):''}<div class=lpjb><div><b>Laporan Pertanggungjawaban (LPJ)</b><small>${r.disb?(r.lpj&&r.lpj.note?'Catatan pimpinan: '+esc(r.lpj.note):r.status=='Selesai'?'Nota sudah di-ACC. LPJ dapat diunduh sebagai PDF.':r.lpj&&r.lpj.st=='Menunggu verifikasi'?'Nota sedang diperiksa pimpinan.':'Kirim ke pimpinan setelah seluruh nota lengkap.'):'LPJ dapat dibuat setelah dana dicairkan.'}</small></div><div>${r.disb?'<button class="btn o" onclick="lpjView()">Preview / Generate LPJ (PDF)</button>':''}${open&&r.disb?`<button class="btn g" onclick="act('lpjsend')">Kirim ke Pimpinan untuk ACC</button>`:''}</div></div>
</div>`}
const stp=noPay(r)?['Diajukan + nota','Disetujui','Selesai']:isRb(r)?['Diajukan + nota','Disetujui','Dibayarkan','Selesai']:['Diajukan','Disetujui','Dicairkan','Pertanggungjawaban','Selesai'],si=(noPay(r)?{'Selesai':2}:isRb(r)?{'Disetujui':1,'Selesai':3}:{'Draft':0,'Menunggu persetujuan':0,'Perlu revisi':0,'Disetujui':1,'Dana dicairkan':2,'Dalam pertanggungjawaban':3,'Selesai':4})[r.status]??0,hn=(r.hist.slice().reverse().find(h=>h.s==r.status)||{}).n||'-';
return `<div class=box><div class=dtop><button class="btn o bk" onclick="go('list')">${SV.back} Kembali</button><div class=dact>${bolehHapus(r)?`<button type=button class=btn-del onclick="hapusReq()" title="Hapus request ini secara permanen">${NI.trash}<span>Hapus request</span></button>`:''}<span class="${bc(r.status)} big">${r.status}</span></div></div>
<div class=dti><small class=mu>Nomor request</small><h3>${r.no}${jTag(r)}</h3><div class=dtt>${esc(r.title)}</div></div>${jnBar(r)}
${['Ditolak','Perlu revisi'].includes(r.status)?`<div class=ban>${SV.x}<div><b>${r.status=='Ditolak'?'Request ditolak':'Perlu revisi'}</b><div>${esc(hn)}</div></div></div>`:''}
${ckTop(r,m)}${rabTop(r,m)}${r.status=='Ditolak'?'':`<div class=stp>${stp.map((t,k)=>`<div class="st ${k<si?'ok':k==si?'cu':''}"><i>${k<si?SV.chk:k+1}</i><span>${t}</span></div>`).join('')}</div>`}
<div class=amts><div class=am><small>Diajukan</small><b>${Rp(r.amt)}</b></div>${r.rab?`<div class=am><small>Total RAB</small><b>${Rp(r.rab.total)}</b></div>`:''}<div class=am><small>Disetujui</small><b>${r.approved!=null?Rp(r.approved):'-'}</b>${r.approved!=null&&r.approved!=r.amt?`<em>${r.approved<r.amt?'Dikurangi':'Ditambah'} ${Rp(Math.abs(r.amt-r.approved))}</em>`:''}</div><div class=am><small>${noPay(r)?'Sumber dana':isRb(r)?'Dibayarkan':'Dicairkan'}</small><b>${noPay(r)?SRCN(r):r.disb?Rp(r.disb.amt):'-'}</b>${r.disb?`<em>${r.disb.date} · ${esc(r.disb.method)}</em>${tfLink(r)}`:''}</div></div>
<div class=inf><div class=if><span class=ci>${IC.users}</span><div><small>Bendahara</small><b>${esc(r.by)}</b></div></div><div class=if><span class=ci>${IC.list}</span><div><small>Kategori</small><b>${esc(r.cat)}</b></div></div><div class=if><span class=ci>${SV.cal}</span><div><small>Tanggal pengajuan</small><b>${r.date}</b></div></div><div class=if><span class=ci>${SV.cal}</span><div><small>Dana dibutuhkan</small><b>${r.need}</b></div></div></div>
<div class=desc><small>Deskripsi kebutuhan</small><p>${esc(r.desc)||'<span class=mu>Tidak ada deskripsi.</span>'}</p></div>
${r.file?fLink(r.file,'Dokumen pendukung '+r.no):''}
${m=='Bendahara'&&!(r.rab&&['Draft','Perlu revisi'].includes(r.status))&&!(r.status=='Draft'&&!isRb(r))?`<div class=lockb>${SV.lock}<span>${r.status=='Selesai'?'Request selesai. Data dan nota sudah terkunci.':(rbOpen(r)?'Lampirkan nota di bawah, lalu kirim ke pimpinan.':isRb(r)?'Data dan nota terkunci. Tidak perlu mengunggah nota lagi.':'Data request terkunci dan tidak dapat diubah. Anda hanya dapat mengunggah bukti nota.')}</span></div>`:''}</div>
${rabBox(r)}${a?`<div class=box>${a}</div>`:''}${tx}${m=='Admin'&&r.lpj&&r.lpj.st=='Menunggu verifikasi'?ckPanel(r):''}<div class=box><h4>Riwayat</h4><div class=hrow>${r.hist.map(h=>`<div class=hs><b>${esc(h.s)}</b>${h.n?`<div>${esc(h.n)}</div>`:''}<small>${esc(h.u)}</small><small>${h.t}</small></div>`).join('')||'<small class=mu>Belum ada riwayat.</small>'}</div></div>`}
