const LIVE=['dash','list','notif','audit','rep','lpjm'];
async function pull(){if(!S.me||document.hidden)return;try{const d=await API.poll();if(!d)return;mergeS(d);const a=document.activeElement,typing=a&&/^(INPUT|TEXTAREA|SELECT)$/.test(a.tagName),busyUI=DO||$('lb').style.display=='flex'||$('pv').style.display=='block'||($('fdd')&&$('fdd').classList.contains('open'));if(LIVE.includes(v)&&!typing&&!busyUI)draw();else{const b=document.querySelector('.bell'),n=S.notes.filter(x=>x.role==me().role&&!x.read).length;if(b){const em=b.querySelector('em');if(n){if(em)em.textContent=n;else b.insertAdjacentHTML('beforeend','<em>'+n+'</em>')}else if(em)em.remove()}}}catch(e){}}
setInterval(pull,10000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)pull()});
(async()=>{try{const r=await API.session();await boot(r.user)}catch(e){if(e.net){$('app').innerHTML='<div id=boot>Tidak dapat terhubung ke server. <button class=btn onclick="location.reload()">Coba lagi</button></div>'}else draw()}})();
